#include <chrono>
#include <iomanip>
#include <iostream>
#include <vector> // for per‑column recursion buffers

#include <noarr/traversers.hpp>

#include "defines.hpp"
#include "deriche.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// img[i][j] with j the innermost (contiguous) dimension, as in C (img[W][H])
	DEFINE_PROTO_STRUCT(img_layout, j_vec ^ i_vec);

	// Tunable column block size for the vertical (i-direction) passes.
	// Columns are processed in blocks of this width so that the per-column
	// recursion state for each block fits well into the L1/L2 caches.
	static constexpr std::size_t col_block_size = 128;
} tuning;

// initialization function
// imgIn, imgOut: i x j
void init_array(num_t &alpha, auto imgIn, auto imgOut) {
	using namespace noarr;
	(void)imgOut; // not used, kept for interface similarity

	alpha = SCALAR_VAL(0.25); // parameter of the filter

	// input should be between 0 and 1 (grayscale image pixel)
	traverser(imgIn).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		imgIn[state] = (num_t)(((313 * i + 991 * j) % 65536) / 65535.0f);
	});
}

// computation kernel
// imgIn, imgOut, y1, y2: i x j
// Layout is row-major: 'i' is the outer (row) dimension, 'j' is contiguous.
[[gnu::flatten, gnu::noinline]]
void kernel_deriche(num_t alpha, auto imgIn, auto imgOut, auto y1, auto y2) {
	using namespace noarr;

	num_t k;
	num_t a1, a2, a3, a4, a5, a6, a7, a8;
	num_t b1, b2, c1, c2;

#pragma scop
	// ---------------------------------------------------------------------
	// Coefficient setup (unchanged from C version)
	// ---------------------------------------------------------------------
	k = (SCALAR_VAL(1.0) - EXP_FUN(-alpha)) *
	    (SCALAR_VAL(1.0) - EXP_FUN(-alpha)) /
	    (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * alpha * EXP_FUN(-alpha) - EXP_FUN(SCALAR_VAL(2.0) * alpha));
	a1 = a5 = k;
	a2 = a6 = k * EXP_FUN(-alpha) * (alpha - SCALAR_VAL(1.0));
	a3 = a7 = k * EXP_FUN(-alpha) * (alpha + SCALAR_VAL(1.0));
	a4 = a8 = -k * EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
	b2 = -EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	c1 = c2 = SCALAR_VAL(1.0);

	// lengths used for reverse traversals
	const std::size_t w_len = imgIn | get_length<'i'>();
	const std::size_t h_len = imgIn | get_length<'j'>();

	// ---------------------------------------------------------------------
	// 1st pass: causal filter along j, for each i (forward j)
	//
	// for (i=0; i<W; i++)
	//   ym1=0; ym2=0; xm1=0;
	//   for (j=0; j<H; j++)
	//     y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2; ...
	//
	// Implemented row-by-row: 'i' is fixed in the outer traverser,
	// 'j' is iterated contiguously inside each row.
	// ---------------------------------------------------------------------
	traverser(y1, imgIn).template for_dims<'i'>([&](auto row_trav) {
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);
		num_t xm1 = SCALAR_VAL(0.0);

		row_trav.template for_each<'j'>([&](auto state) {
			const num_t x = imgIn[state];
			const num_t y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y;

			xm1 = x;
			ym2 = ym1;
			ym1 = y;
		});
	});

	// ---------------------------------------------------------------------
	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	//
	// Original C: j from H-1 down to 0
	//   yp1=0; yp2=0; xp1=0; xp2=0;
	//   for (j=H-1; j>=0; j--)
	//     y2[i][j] = a3*xp1 + a4*xp2 + b1*yp1 + b2*yp2; ...
	//
	// We still traverse j in 0..H-1, but map r -> j = H-1-r so that
	// the memory access along the row remains contiguous while preserving
	// the recursion order.
	// ---------------------------------------------------------------------
	traverser(y2, imgIn).template for_dims<'i'>([&](auto row_trav) {
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);
		num_t xp1 = SCALAR_VAL(0.0);
		num_t xp2 = SCALAR_VAL(0.0);

		// 'i' index is constant for this row; fetch it just once
		const auto base_state = row_trav.state();
		const std::size_t i_idx = get_index<'i'>(base_state);

		row_trav.template for_each<'j'>([&](auto state) {
			const std::size_t j_fwd = get_index<'j'>(state);
			const std::size_t j_idx = h_len - 1 - j_fwd; // reverse j

			const num_t x = imgIn.template at<'i', 'j'>(i_idx, j_idx);
			const num_t y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

			y2.template at<'i', 'j'>(i_idx, j_idx) = y;

			xp2 = xp1;
			xp1 = x;
			yp2 = yp1;
			yp1 = y;
		});
	});

	// ---------------------------------------------------------------------
	// Combine vertical passes (after first horizontal filtering)
	//
	// imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	// ---------------------------------------------------------------------
	traverser(imgOut, y1, y2).for_each([&](auto state) {
		imgOut[state] = c1 * (y1[state] + y2[state]);
	});

	// ---------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (forward i)
	//
	// Naive column-wise version (original C):
	//   for (j=0; j<H; j++)
	//     tm1=0; ym1=0; ym2=0;
	//     for (i=0; i<W; i++)
	//       y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2; ...
	//
	// That version walks down columns in a row-major layout, which produces
	// strided memory accesses.
	//
	// Optimized version below:
	//   - We process the image row-wise (i-major, j-minor) using a traverser.
	//   - For each column j we keep the recursive state (tm1, ym1, ym2) in
	//     small temporary arrays, indexed by column-local index.
	//   - We also block the columns into stripes of width col_block_size
	//     so that the per-column state for a stripe fits comfortably into cache.
	//
	// This reorders independent operations across columns but preserves the
	// per-column recursion order along i, hence the numerical result is the
	// same up to floating‑point round-off.
	// ---------------------------------------------------------------------
	const std::size_t col_block = tuning.col_block_size;

	// Scratch buffers for the causal vertical pass (size col_block, reused per stripe)
	std::vector<num_t> tm1(col_block);
	std::vector<num_t> ym1(col_block);
	std::vector<num_t> ym2(col_block);

	for (std::size_t j0 = 0; j0 < h_len; j0 += col_block) {
		const std::size_t jb_len = (j0 + col_block <= h_len) ? col_block : (h_len - j0);

		// Reset recursion state for this column stripe
		for (std::size_t jl = 0; jl < jb_len; ++jl) {
			tm1[jl] = SCALAR_VAL(0.0);
			ym1[jl] = SCALAR_VAL(0.0);
			ym2[jl] = SCALAR_VAL(0.0);
		}

		// Restrict the traverser to the current column stripe [j0, j0+jb_len)
		auto col_slice = slice<'j'>(j0, jb_len);

		traverser(y1, imgOut).order(col_slice).for_each([&](auto state) {
			const std::size_t j_global = get_index<'j'>(state);
			const std::size_t j_local  = j_global - j0; // 0 .. jb_len-1

			num_t &tm1j = tm1[j_local];
			num_t &ym1j = ym1[j_local];
			num_t &ym2j = ym2[j_local];

			const num_t x = imgOut[state];
			const num_t y = a5 * x + a6 * tm1j + b1 * ym1j + b2 * ym2j;

			y1[state] = y;

			tm1j = x;
			ym2j = ym1j;
			ym1j = y;
		});
	}

	// ---------------------------------------------------------------------
	// 4th pass: anti-causal filter along i, for each j (reverse i)
	//
	// Original C, column-wise:
	//   for (j=0; j<H; j++)
	//     tp1=0; tp2=0; yp1=0; yp2=0;
	//     for (i=W-1; i>=0; i--)
	//       y2[i][j] = a7*tp1 + a8*tp2 + b1*yp1 + b2*yp2; ...
	//
	// Again this walks columns in a row-major layout.
	//
	// Optimized version:
	//   - We still maintain one set of recursion scalars per column, but
	//     stored in temporary arrays of size col_block_size.
	//   - We process stripes of columns; within a stripe we traverse the image
	//     row-wise using a single traverser, and map the forward row index
	//     i_fwd to the anti-causal index i_idx = W-1-i_fwd.
	//   - For each column the sequence of (i_idx) values is still W-1, W-2, ... 0,
	//     so recursion semantics are preserved, while memory access along rows
	//     becomes contiguous.
	// ---------------------------------------------------------------------
	std::vector<num_t> tp1(col_block);
	std::vector<num_t> tp2(col_block);
	std::vector<num_t> yp1(col_block);
	std::vector<num_t> yp2(col_block);

	for (std::size_t j0 = 0; j0 < h_len; j0 += col_block) {
		const std::size_t jb_len = (j0 + col_block <= h_len) ? col_block : (h_len - j0);

		// Reset recursion state for this column stripe
		for (std::size_t jl = 0; jl < jb_len; ++jl) {
			tp1[jl] = SCALAR_VAL(0.0);
			tp2[jl] = SCALAR_VAL(0.0);
			yp1[jl] = SCALAR_VAL(0.0);
			yp2[jl] = SCALAR_VAL(0.0);
		}

		auto col_slice = slice<'j'>(j0, jb_len);

		traverser(y2, imgOut).order(col_slice).for_each([&](auto state) {
			const std::size_t i_fwd    = get_index<'i'>(state);        // 0 .. W-1
			const std::size_t j_global = get_index<'j'>(state);        // in [j0, j0+jb_len)
			const std::size_t j_local  = j_global - j0;                // 0 .. jb_len-1
			const std::size_t i_idx    = w_len - 1u - i_fwd;           // reversed row index

			num_t &tp1j = tp1[j_local];
			num_t &tp2j = tp2[j_local];
			num_t &yp1j = yp1[j_local];
			num_t &yp2j = yp2[j_local];

			const num_t y = a7 * tp1j + a8 * tp2j + b1 * yp1j + b2 * yp2j;
			y2.template at<'i', 'j'>(i_idx, j_global) = y;

			tp2j = tp1j;
			const num_t x = imgOut.template at<'i', 'j'>(i_idx, j_global);
			tp1j = x;
			yp2j = yp1j;
			yp1j = y;
		});
	}

	// ---------------------------------------------------------------------
	// Final combine
	//
	// imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
	// ---------------------------------------------------------------------
	traverser(imgOut, y1, y2).for_each([&](auto state) {
		imgOut[state] = c2 * (y1[state] + y2[state]);
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t w = W;
	std::size_t h = H;

	// parameter
	num_t alpha;

	// lengths shared by all images
	auto set_lengths =
		noarr::set_length<'i'>(w) ^
		noarr::set_length<'j'>(h);

	// images: i x j
	auto imgIn  = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto imgOut = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y1     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y2     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);

	// initialize data
	init_array(alpha, imgIn.get_ref(), imgOut.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_deriche(alpha, imgIn.get_ref(), imgOut.get_ref(), y1.get_ref(), y2.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (acts as DCE prevention)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, imgOut.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
