#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp> // for noarr::serialize_data

#include "defines.hpp"
#include "deriche.hpp"

using num_t = DATA_TYPE;

namespace {

// basic 2D layout
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// Tunable parameters that influence the kernel behaviour/layout.
// They are constexpr so that the compiler can aggressively optimize
// the code paths selected here.
struct tuning {
	// img[i][j] with j the innermost (contiguous) dimension, as in C (img[W][H])
	// If you want to experiment with a layout that is contiguous in 'i',
	// you can replace this with (i_vec ^ j_vec) and recompile.
	DEFINE_PROTO_STRUCT(img_layout, j_vec ^ i_vec);

	// Reserved for potential future tuning of the kernel (e.g. blocking
	// factors, OpenMP tiling, etc.). Keeping them here makes it easy to
	// experiment without touching the algorithmic code.
	static constexpr std::size_t block_i = 64; // currently unused, placeholder
	static constexpr std::size_t block_j = 64; // currently unused, placeholder
} tuning;

// -----------------------------------------------------------------------------
// initialization function
// imgIn, imgOut: i x j
// -----------------------------------------------------------------------------
void init_array(num_t &alpha, auto imgIn, auto imgOut) {
	using namespace noarr;
	(void)imgOut; // not used, kept for interface similarity

	alpha = SCALAR_VAL(0.25); // parameter of the filter

	// input should be between 0 and 1 (grayscale image pixel)
	// Traversal order is i-major/j-minor, but the actual layout is
	// abstracted by Noarr and controlled via tuning.img_layout.
	traverser(imgIn).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		imgIn[state] = (num_t)(((313 * i + 991 * j) % 65536) / 65535.0f);
	});
}

// -----------------------------------------------------------------------------
// computation kernel
// imgIn, imgOut, y1, y2: i x j
//
// This is a direct Noarr-based implementation of the 2D Deriche
// recursive IIR filter. The main optimizations compared to a naive
// translation are:
//
//  * Coefficient precomputation with reduced calls to EXP_FUN/POW_FUN.
//  * Reduced redundant memory accesses: per-element values are loaded
//    once into local temporaries instead of repeatedly via imgIn[state]
//    / imgOut[state] / y1[state] / y2[state].
//  * Reverse passes implemented using index-state arithmetic instead of
//    repeatedly reconstructing full states via get_indices + idx.
//
// All traversals are expressed using Noarr traversers as required.
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_deriche(num_t alpha, auto imgIn, auto imgOut, auto y1, auto y2) {
	using namespace noarr;

	num_t k;
	num_t a1, a2, a3, a4, a5, a6, a7, a8;
	num_t b1, b2, c1, c2;

#pragma scop
	// ---------------------------------------------------------------------
	// Coefficient setup
	//
	// We hoist common exponentials to temporaries so they are computed
	// only once. This is particularly beneficial when EXP_FUN/POW_FUN
	// map to libm calls.
	// ---------------------------------------------------------------------
	const num_t exp_neg_alpha  = EXP_FUN(-alpha);
	const num_t exp_neg_2alpha = EXP_FUN(SCALAR_VAL(-2.0) * alpha);

	k = (SCALAR_VAL(1.0) - exp_neg_alpha) *
	    (SCALAR_VAL(1.0) - exp_neg_alpha) /
	    (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * alpha * exp_neg_alpha - exp_neg_2alpha);

	a1 = a5 = k;
	a2 = a6 = k * exp_neg_alpha * (alpha - SCALAR_VAL(1.0));
	a3 = a7 = k * exp_neg_alpha * (alpha + SCALAR_VAL(1.0));
	a4 = a8 = -k * exp_neg_2alpha;

	b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
	b2 = -exp_neg_2alpha;

	c1 = c2 = SCALAR_VAL(1.0);

	// lengths used for reverse traversals
	const std::size_t w_len = imgIn | get_length<'i'>();
	const std::size_t h_len = imgIn | get_length<'j'>();

	// ---------------------------------------------------------------------
	// 1st pass: causal filter along j, for each i (forward j)
	//
	// For each fixed i we apply a 1D causal recursion along j.
	// Optimizations:
	//   * Per-element imgIn/state loaded once into 'x'
	//   * Computed output stored once and reused via local 'y'
	//     instead of re-reading y1[state].
	// ---------------------------------------------------------------------
	traverser(y1, imgIn).template for_dims<'i'>([&](auto inner) {
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);
		num_t xm1 = SCALAR_VAL(0.0);

		inner.template for_each<'j'>([&](auto state) {
			const num_t x = imgIn[state];
			const num_t y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y;

			xm1 = x;
			ym2 = ym1;
			ym1 = y;
		});
	});

	// ---------------------------------------------------------------------
	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	//
	// Original C loops j from H-1 down to 0. We traverse j in 0..H-1
	// (forward) but map the iteration index to a reversed index:
	//   r = 0..H-1  -->  j = H-1-r
	//
	// Instead of reconstructing the reversed state via:
	//     get_indices + idx<'i','j'>(i_idx, j_idx)
	// on every iteration, we:
	//   * Obtain a base state with 'i' fixed once per row via inner.state()
	//   * Maintain a plain size_t j_rev that we decrement
	//   * Construct rev_state by base_state + idx<'j'>(j_rev)
	// This keeps all arithmetic in simple scalars and minimizes State
	// construction overhead while still staying fully within Noarr.
	// ---------------------------------------------------------------------
	traverser(y2, imgIn).template for_dims<'i'>([&](auto inner) {
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);
		num_t xp1 = SCALAR_VAL(0.0);
		num_t xp2 = SCALAR_VAL(0.0);

		// State with 'i' fixed, used as a base for constructing reversed
		// j indices. The Noarr state is immutable; plus() returns a new
		// state without mutating base_state.
		const auto base_state = inner.state();
		std::size_t j_rev = h_len - 1;

		inner.template for_each<'j'>([&](auto /*forward_state*/) {
			const auto rev_state = base_state + idx<'j'>(j_rev);

			const num_t x = imgIn[rev_state];
			const num_t y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

			y2[rev_state] = y;

			xp2 = xp1;
			xp1 = x;
			yp2 = yp1;
			yp1 = y;

			--j_rev;
		});
	});

	// ---------------------------------------------------------------------
	// Combine vertical passes
	// imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	//
	// This materializes the vertically filtered image into imgOut,
	// which then serves as the input signal for the horizontal passes.
	// ---------------------------------------------------------------------
	traverser(imgOut, y1, y2).for_each([&](auto state) {
		imgOut[state] = c1 * (y1[state] + y2[state]);
	});

	// ---------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (forward i)
	//
	// For each fixed j we apply a 1D causal recursion along i.
	// As in the first pass, we avoid redundant loads:
	//   * imgOut[state] is read once into 'x'
	//   * y1[state] written once and reused via 'y'
	// ---------------------------------------------------------------------
	traverser(y1, imgOut).template for_dims<'j'>([&](auto inner) {
		num_t tm1 = SCALAR_VAL(0.0);
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);

		inner.template for_each<'i'>([&](auto state) {
			const num_t x = imgOut[state];
			const num_t y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y;

			tm1 = x;
			ym2 = ym1;
			ym1 = y;
		});
	});

	// ---------------------------------------------------------------------
	// 4th pass: anti-causal filter along i, for each j (reverse i)
	//
	// Original C loops i from W-1 down to 0. We again traverse i in
	// 0..W-1 (forward) and map r -> i = W-1-r using state arithmetic.
	//
	// As in the 2nd pass, we:
	//   * Obtain a base state with 'j' fixed once per column
	//   * Maintain a scalar i_rev that we decrement
	//   * Construct rev_state by base_state + idx<'i'>(i_rev)
	// ---------------------------------------------------------------------
	traverser(y2, imgOut).template for_dims<'j'>([&](auto inner) {
		num_t tp1 = SCALAR_VAL(0.0);
		num_t tp2 = SCALAR_VAL(0.0);
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);

		const auto base_state = inner.state(); // 'j' fixed
		std::size_t i_rev = w_len - 1;

		inner.template for_each<'i'>([&](auto /*forward_state*/) {
			const auto rev_state = base_state + idx<'i'>(i_rev);

			const num_t x = imgOut[rev_state];
			const num_t y = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;

			y2[rev_state] = y;

			tp2 = tp1;
			tp1 = x;
			yp2 = yp1;
			yp1 = y;

			--i_rev;
		});
	});

	// ---------------------------------------------------------------------
	// Final combine
	// imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
	// ---------------------------------------------------------------------
	traverser(imgOut, y1, y2).for_each([&](auto state) {
		imgOut[state] = c2 * (y1[state] + y2[state]);
	});
#pragma endscop
}

} // namespace

// -----------------------------------------------------------------------------
// main: boilerplate kept intact (allocation, initialization, timing, printing)
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
