using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// img[i][j] with j the innermost (contiguous) dimension, as in C (img[W][H])
	DEFINE_PROTO_STRUCT(img_layout, j_vec ^ i_vec);
} tuning;

// initialization function
// imgIn, imgOut: i x j
void init_array(num_t &alpha, auto imgIn, auto imgOut) {
	using namespace noarr;
	(void)imgOut; // not used, kept for interface similarity

	alpha = SCALAR_VAL(0.25); // parameter of the filter

	// input should be between 0 and 1 (grayscale image pixel)
	traverser(imgIn).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		imgIn[state] = (num_t)(((313 * i + 991 * j) % 65536) / 65535.0f);
	});
}

// computation kernel
// imgIn, imgOut, y1, y2: i x j
//
// Optimizations compared to the baseline version:
//  * The two “combine” passes are fused into the corresponding
//    anti‑causal passes, eliminating two full traversals of the image.
//  * The temporary array y2 is no longer used as storage; the
//    anti‑causal passes keep y2 values only in registers and combine
//    immediately with y1, reducing memory traffic.
//  * Within each inner loop, values from imgIn/imgOut and y1 are
//    loaded once into local variables and then reused, improving the
//    compiler’s ability to keep them in registers and avoid redundant
//    loads.
//  * Reverse traversals are still implemented via forward traversals
//    over a “reversed” index computed from the known lengths; this
//    preserves the original recurrence semantics exactly.
[[gnu::flatten, gnu::noinline]]
void kernel_deriche(num_t alpha, auto imgIn, auto imgOut, auto y1, auto y2) {
	using namespace noarr;

	// tunable compile-time constants (not used for control flow here,
	// but kept as explicit knobs for future tiling / blocking
	// experiments if desired).
	[[maybe_unused]] constexpr std::size_t vertical_block_size   = 64;
	[[maybe_unused]] constexpr std::size_t horizontal_block_size = 64;

	num_t k;
	num_t a1, a2, a3, a4, a5, a6, a7, a8;
	num_t b1, b2, c1, c2;

#pragma scop
	// coefficient setup (unchanged from C version)
	k = (SCALAR_VAL(1.0) - EXP_FUN(-alpha)) *
	    (SCALAR_VAL(1.0) - EXP_FUN(-alpha)) /
	    (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * alpha * EXP_FUN(-alpha) - EXP_FUN(SCALAR_VAL(2.0) * alpha));
	a1 = a5 = k;
	a2 = a6 = k * EXP_FUN(-alpha) * (alpha - SCALAR_VAL(1.0));
	a3 = a7 = k * EXP_FUN(-alpha) * (alpha + SCALAR_VAL(1.0));
	a4 = a8 = -k * EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
	b2 = -EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	c1 = c2 = SCALAR_VAL(1.0);

	// lengths used for reverse traversals
	const std::size_t w_len   = imgIn | get_length<'i'>();
	const std::size_t h_len   = imgIn | get_length<'j'>();
	const std::size_t last_i  = w_len - 1u;
	const std::size_t last_j  = h_len - 1u;

	// --------------------------------------------------------------------
	// 1st pass: causal filter along j, for each i (forward j)
	//
	// Original C:
	//   for (i=0; i<W; i++) {
	//     ym1=0; ym2=0; xm1=0;
	//     for (j=0; j<H; j++) {
	//       y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2;
	//       xm1 = imgIn[i][j];
	//       ym2 = ym1;
	//       ym1 = y1[i][j];
	//     }
	//   }
	// We keep the same traversal order but express it via Noarr traversers.
	// --------------------------------------------------------------------
	traverser(y1, imgIn).template for_dims<'i'>([&](auto row_trav) {
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);
		num_t xm1 = SCALAR_VAL(0.0);

		row_trav.template for_each<'j'>([&](auto state) {
			const num_t x   = imgIn[state];
			const num_t y_v = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y_v;

			xm1 = x;
			ym2 = ym1;
			ym1 = y_v;
		});
	});

	// --------------------------------------------------------------------
	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	//
	// Original C: j from H-1 down to 0, producing y2[i][j], then a
	// separate pass does:
	//   imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	//
	// Here we traverse j in 0..H-1, map r -> j = H-1-r, and *fuse* the
	// vertical combine step so we never materialize y2 in memory:
	//   - compute y2 value into a local scalar y2_v
	//   - update the recurrence state from y2_v and imgIn
	//   - immediately combine with y1[i][j] and store into imgOut[i][j]
	//
	// This reduces memory traffic while preserving the original
	// recurrence semantics exactly, because the recurrence only needs
	// the newly computed y2 value for the current position (which we
	// keep in y2_v) and not the full y2 array.
	// --------------------------------------------------------------------
	traverser(imgIn, y1, imgOut).template for_dims<'i'>([&](auto row_trav) {
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);
		num_t xp1 = SCALAR_VAL(0.0);
		num_t xp2 = SCALAR_VAL(0.0);

		row_trav.template for_each<'j'>([&](auto state) {
			auto [i_idx, r_j] = get_indices<'i', 'j'>(state);
			const std::size_t j_idx = last_j - r_j;
			auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

			// anti-causal recurrence at (i_idx, j_idx)
			const num_t y2_v = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

			// update recurrence state using original input
			xp2 = xp1;
			const num_t x = imgIn[rev_state];
			xp1 = x;
			yp2 = yp1;
			yp1 = y2_v;

			// fuse vertical combine: imgOut = c1 * (y1 + y2)
			const num_t y1_v = y1[rev_state];
			imgOut[rev_state] = c1 * (y1_v + y2_v);
		});
	});

	// --------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (forward i)
	//
	// Original C:
	//   for (j=0; j<H; j++) {
	//     tm1=0; ym1=0; ym2=0;
	//     for (i=0; i<W; i++) {
	//       y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2;
	//       tm1 = imgOut[i][j];
	//       ym2 = ym1;
	//       ym1 = y1[i][j];
	//     }
	//   }
	//
	// We again keep the traversal order but use Noarr traversers.
	// --------------------------------------------------------------------
	traverser(y1, imgOut).template for_dims<'j'>([&](auto col_trav) {
		num_t tm1 = SCALAR_VAL(0.0);
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);

		col_trav.template for_each<'i'>([&](auto state) {
			const num_t x   = imgOut[state];
			const num_t y_v = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y_v;

			tm1 = x;
			ym2 = ym1;
			ym1 = y_v;
		});
	});

	// --------------------------------------------------------------------
	// 4th pass: anti-causal filter along i, for each j (reverse i)
	//
	// Original C: i from W-1 down to 0, producing y2[i][j], then a final
	// combine:
	//   imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
	//
	// As in the vertical direction, we:
	//   - traverse i in 0..W-1, mapping r -> i = W-1-r
	//   - compute the y2 value into a scalar y2_v
	//   - update recurrence state from y2_v and the original imgOut
	//   - immediately combine with y1[i][j] into the *final* imgOut
	//
	// Note: we always read the original (pre-horizontal) imgOut value
	// for the recurrence before overwriting imgOut with the final
	// result, so the recurrence still sees the same data as in the
	// baseline code.
	// --------------------------------------------------------------------
	traverser(imgOut, y1).template for_dims<'j'>([&](auto col_trav) {
		num_t tp1 = SCALAR_VAL(0.0);
		num_t tp2 = SCALAR_VAL(0.0);
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);

		col_trav.template for_each<'i'>([&](auto state) {
			auto [r_i, j_idx] = get_indices<'i', 'j'>(state);
			const std::size_t i_idx = last_i - r_i;
			auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

			// anti-causal recurrence at (i_idx, j_idx)
			const num_t y2_v = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;

			// update recurrence state using the original vertical output
			tp2 = tp1;
			const num_t x = imgOut[rev_state]; // original (vertical) output
			tp1 = x;
			yp2 = yp1;
			yp1 = y2_v;

			// final combine: overwrite imgOut in-place
			const num_t y1_v = y1[rev_state];
			imgOut[rev_state] = c2 * (y1_v + y2_v);
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
