		row_trav.for_each([&](auto state) {
			const num_t x0 = imgIn[state];
			const num_t y0 = a1 * x0 + a2 * xm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y0;

			xm1 = x0;
			ym2 = ym1;
			ym1 = y0;
