		const auto base_state = row_trav.state();
		const std::size_t i_idx = get_index<'i'>(base_state);

		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);
		num_t xp1 = SCALAR_VAL(0.0);
		num_t xp2 = SCALAR_VAL(0.0);

		std::size_t r_j = 0; // forward counter, mapped to reverse j

		row_trav.for_each([&](auto /*state*/) {
			const std::size_t j_idx = h_len - 1 - r_j;
			++r_j;

			auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

			const num_t x0 = imgIn[rev_state];
			const num_t y0 = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

			// store vertical anti-causal result
			y2[rev_state] = y0;
			// fuse: imgOut = c1 * (y1 + y2) (vertical combine)
			imgOut[rev_state] = c1 * (y1[rev_state] + y0);

			xp2 = xp1;
			xp1 = x0;
			yp2 = yp1;
			yp1 = y0;
		});
	});

