#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/structures_extended.hpp>
#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

#include "defines.hpp"
#include "deriche.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// img[i][j] with j the innermost (contiguous) dimension, as in C (img[W][H])
	DEFINE_PROTO_STRUCT(img_layout, j_vec ^ i_vec);

	// Tuning knobs (can be changed for experimentation / different hardware)
	static constexpr bool use_reversed_state_traversal = true;
} tuning;

// initialization function
// imgIn, imgOut: i x j
void init_array(num_t &alpha, auto imgIn, auto imgOut) {
	using namespace noarr;
	(void)imgOut; // not used, kept for interface similarity

	alpha = SCALAR_VAL(0.25); // parameter of the filter

	// input should be between 0 and 1 (grayscale image pixel)
	traverser(imgIn).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		imgIn[state] = (num_t)(((313 * i + 991 * j) % 65536) / 65535.0f);
	});
}

// computation kernel
// imgIn, imgOut, y1, y2: i x j
//
// The implementation here follows the original PolyBench DERICHE kernel,
// but is carefully organized around Noarr traversers to:
//   * minimize recomputation of coefficients,
//   * keep inner loops on the contiguous 'j' dimension whenever possible,
//   * avoid repeated index decoding / state construction in reverse passes,
//   * keep all loop nests expressed in terms of traversers.
[[gnu::flatten, gnu::noinline]]
void kernel_deriche(num_t alpha, auto imgIn, auto imgOut, auto y1, auto y2) {
	using namespace noarr;

	// ---------------------------------------------------------------------
	// Coefficient setup
	// ---------------------------------------------------------------------
	// Cache expensive transcendental computations once; they are scalar and
	// independent of the image contents. This keeps the mathematical
	// expression identical to the original C code, just avoiding redundant
	// calls to EXP_FUN / POW_FUN.
	const num_t one  = SCALAR_VAL(1.0);
	const num_t two  = SCALAR_VAL(2.0);
	const num_t neg_alpha = -alpha;

	const num_t exp_neg_alpha   = EXP_FUN(neg_alpha);
	const num_t exp_neg_2alpha  = EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	const num_t exp_pos_2alpha  = EXP_FUN(SCALAR_VAL(2.0) * alpha);
	const num_t pow2_neg_alpha  = POW_FUN(SCALAR_VAL(2.0), neg_alpha);

	num_t k =
		(one - exp_neg_alpha) * (one - exp_neg_alpha) /
		(one + two * alpha * exp_neg_alpha - exp_pos_2alpha);

	num_t a1 = k;
	num_t a2 = k * exp_neg_alpha * (alpha - one);
	num_t a3 = k * exp_neg_alpha * (alpha + one);
	num_t a4 = -k * exp_neg_2alpha;

	// Horizontal coefficients share the same values.
	num_t a5 = a1;
	num_t a6 = a2;
	num_t a7 = a3;
	num_t a8 = a4;

	num_t b1 = pow2_neg_alpha;
	num_t b2 = -exp_neg_2alpha;

	num_t c1 = one;
	num_t c2 = one;

	// lengths used for reverse traversals (dynamic, image-size dependent)
	const std::size_t w_len = imgIn | get_length<'i'>();
	const std::size_t h_len = imgIn | get_length<'j'>();

#pragma scop
	// ---------------------------------------------------------------------
	// 1st pass: causal filter along j, for each i (forward j)
	//
	// Original C:
	// for (i=0; i<W; i++) {
	//   ym1=0; ym2=0; xm1=0;
	//   for (j=0; j<H; j++) {
	//     y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2;
	//     xm1 = imgIn[i][j];
	//     ym2 = ym1;
	//     ym1 = y1[i][j];
	//   }
	// }
	//
	// Here we keep the same logical order but
	//   * traverse 'i' using for_dims<'i'> (rows are independent),
	//   * traverse 'j' using for_each<'j'> (inner contiguous dimension),
	//   * avoid multiple loads/stores per element by caching imgIn[state]
	//     and y1[state] into scalars.
	traverser(y1, imgIn).template for_dims<'i'>([&](auto inner_row) {
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);
		num_t xm1 = SCALAR_VAL(0.0);

		inner_row.template for_each<'j'>([&](auto state) {
			const num_t x_cur = imgIn[state];
			const num_t y_cur = a1 * x_cur + a2 * xm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y_cur;

			xm1 = x_cur;
			ym2 = ym1;
			ym1 = y_cur;
		});
	});

	// ---------------------------------------------------------------------
	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	//
	// Original C:
	// for (i=0; i<W; i++) {
	//   yp1=0; yp2=0; xp1=0; xp2=0;
	//   for (j=H-1; j>=0; j--) {
	//     y2[i][j] = a3*xp1 + a4*xp2 + b1*yp1 + b2*yp2;
	//     xp2 = xp1;
	//     xp1 = imgIn[i][j];
	//     yp2 = yp1;
	//     yp1 = y2[i][j];
	//   }
	// }
	//
	// We still walk j in the reverse direction in terms of the *logical*
	// index, but for performance we:
	//   * use traverser to iterate j forward (0..H-1) as required,
	//   * maintain a separate "reverse" state `rev_state` that we start at
	//     j = H-1 and decrement in each iteration.
	// This keeps accesses along the contiguous 'j' dimension, but avoids
	// recomputing (H-1-j) and constructing a fresh state in every step.
	traverser(y2, imgIn).template for_dims<'i'>([&](auto inner_row) {
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);
		num_t xp1 = SCALAR_VAL(0.0);
		num_t xp2 = SCALAR_VAL(0.0);

		if constexpr (tuning::use_reversed_state_traversal) {
			// Start from (i, j = H-1) and walk backwards in 'j'.
			auto rev_state = inner_row.state() + idx<'j'>(h_len - 1);

			inner_row.template for_each<'j'>([&](auto /*unused*/) {
				const num_t y_cur = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
				const num_t x_cur = imgIn[rev_state];

				y2[rev_state] = y_cur;

				xp2 = xp1;
				xp1 = x_cur;
				yp2 = yp1;
				yp1 = y_cur;

				rev_state = rev_state - idx<'j'>(1);
			});
		} else {
			// Fallback: straightforward mapping j_fwd -> j_rev = H-1-j_fwd.
			inner_row.template for_each<'j'>([&](auto state) {
				auto [i_idx, r_j] = get_indices<'i', 'j'>(state);
				const std::size_t j_idx = h_len - 1 - r_j;
				auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

				const num_t y_cur = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
				const num_t x_cur = imgIn[rev_state];

				y2[rev_state] = y_cur;

				xp2 = xp1;
				xp1 = x_cur;
				yp2 = yp1;
				yp1 = y_cur;
			});
		}
	});

	// ---------------------------------------------------------------------
	// Combine vertical passes:
	//   imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	// ---------------------------------------------------------------------
	traverser(imgOut, y1, y2).for_each([&](auto state) {
		const num_t v = y1[state] + y2[state];
		imgOut[state] = c1 * v;
	});

	// ---------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (forward i)
	//
	// Original C:
	// for (j=0; j<H; j++) {
	//   tm1=0; ym1=0; ym2=0;
	//   for (i=0; i<W; i++) {
	//     y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2;
	//     tm1 = imgOut[i][j];
	//     ym2 = ym1;
	//     ym1 = y1[i][j];
	//   }
	// }
	//
	// Here the recurrence is along 'i'; accesses therefore stride in memory
	// (because 'j' is the contiguous dimension). Data dependencies along
	// 'i' prevent reordering, but we still reduce per-iteration overhead by
	// caching imgOut[state] and y1[state] into scalars.
	traverser(y1, imgOut).template for_dims<'j'>([&](auto inner_col) {
		num_t tm1 = SCALAR_VAL(0.0);
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);

		inner_col.template for_each<'i'>([&](auto state) {
			const num_t x_cur = imgOut[state];
			const num_t y_cur = a5 * x_cur + a6 * tm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y_cur;

			tm1 = x_cur;
			ym2 = ym1;
			ym1 = y_cur;
		});
	});

	// ---------------------------------------------------------------------
	// 4th pass: anti-causal filter along i, for each j (reverse i)
	//
	// Original C:
	// for (j=0; j<H; j++) {
	//   tp1=0; tp2=0; yp1=0; yp2=0;
	//   for (i=W-1; i>=0; i--) {
	//     y2[i][j] = a7*tp1 + a8*tp2 + b1*yp1 + b2*yp2;
	//     tp2 = tp1;
	//     tp1 = imgOut[i][j];
	//     yp2 = yp1;
	//     yp1 = y2[i][j];
	//   }
	// }
	//
	// As with the vertical anti-causal pass we keep a separate "reverse"
	// state that walks (i = W-1 .. 0) while traverser iterates i in
	// forward order (0 .. W-1). This avoids decoding indices and building
	// a new state every iteration, while preserving the original recurrence
	// exactly.
	traverser(y2, imgOut).template for_dims<'j'>([&](auto inner_col) {
		num_t tp1 = SCALAR_VAL(0.0);
		num_t tp2 = SCALAR_VAL(0.0);
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);

		if constexpr (tuning::use_reversed_state_traversal) {
			// Start from (i = W-1, current j) and walk backwards in 'i'.
			auto rev_state = inner_col.state() + idx<'i'>(w_len - 1);

			inner_col.template for_each<'i'>([&](auto /*unused*/) {
				const num_t y_cur = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
				const num_t x_cur = imgOut[rev_state];

				y2[rev_state] = y_cur;

				tp2 = tp1;
				tp1 = x_cur;
				yp2 = yp1;
				yp1 = y_cur;

				rev_state = rev_state - idx<'i'>(1);
			});
		} else {
			inner_col.template for_each<'i'>([&](auto state) {
				auto [r_i, j_idx] = get_indices<'i', 'j'>(state);
				const std::size_t i_idx = w_len - 1 - r_i;
				auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

				const num_t y_cur = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
				const num_t x_cur = imgOut[rev_state];

				y2[rev_state] = y_cur;

				tp2 = tp1;
				tp1 = x_cur;
				yp2 = yp1;
				yp1 = y_cur;
			});
		}
	});

	// ---------------------------------------------------------------------
	// Final combine:
	//   imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
	// ---------------------------------------------------------------------
	traverser(imgOut, y1, y2).for_each([&](auto state) {
		const num_t v = y1[state] + y2[state];
		imgOut[state] = c2 * v;
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t w = W;
	std::size_t h = H;

	// parameter
	num_t alpha;

	// lengths shared by all images
	auto set_lengths =
		noarr::set_length<'i'>(w) ^
		noarr::set_length<'j'>(h);

	// images: i x j
	auto imgIn  = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto imgOut = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y1     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y2     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);

	// initialize data
	init_array(alpha, imgIn.get_ref(), imgOut.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_deriche(alpha, imgIn.get_ref(), imgOut.get_ref(), y1.get_ref(), y2.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (acts as DCE prevention)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, imgOut.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
